export const SEARCH_GRAMMAR_VERSION = 1 as const;

/** UTF-16 source offsets, with an inclusive start and exclusive end. */
export interface SourceRange {
  readonly start: number;
  readonly end: number;
}

export type SearchParseErrorCode =
  | "UNMATCHED_QUOTE"
  | "EMPTY_PHRASE"
  | "EMPTY_TAG"
  | "MISSING_LEFT_OPERAND"
  | "MISSING_RIGHT_OPERAND"
  | "DOUBLE_OPERATOR"
  | "UNSUPPORTED_GROUPING"
  | "UNSUPPORTED_NEGATION"
  | "INVALID_ESCAPE";

export interface SearchParseError {
  readonly code: SearchParseErrorCode;
  readonly message: string;
  readonly hint: string;
  readonly range: SourceRange;
}

export interface EmptySearchNode {
  readonly kind: "Empty";
}

export interface TextSearchNode {
  readonly kind: "Text";
  readonly value: string;
  readonly range: SourceRange;
}

export interface PhraseSearchNode {
  readonly kind: "Phrase";
  readonly value: string;
  readonly range: SourceRange;
}

export interface TagSearchNode {
  readonly kind: "Tag";
  readonly normalizedValue: string;
  readonly displayValue: string;
  readonly range: SourceRange;
}

export interface AndSearchNode {
  readonly kind: "And";
  readonly left: SearchExpression;
  readonly right: SearchExpression;
  readonly range: SourceRange;
}

export interface OrSearchNode {
  readonly kind: "Or";
  readonly left: SearchExpression;
  readonly right: SearchExpression;
  readonly range: SourceRange;
}

export type SearchExpression =
  | TextSearchNode
  | PhraseSearchNode
  | TagSearchNode
  | AndSearchNode
  | OrSearchNode;

export type SearchAst = EmptySearchNode | SearchExpression;

export type SearchParseResult =
  | { readonly ok: true; readonly ast: SearchAst }
  | { readonly ok: false; readonly error: SearchParseError };

export type SearchToken =
  | {
      readonly kind: "text";
      readonly value: string;
      readonly range: SourceRange;
    }
  | {
      readonly kind: "phrase";
      readonly value: string;
      readonly range: SourceRange;
    }
  | {
      readonly kind: "tag";
      readonly normalizedValue: string;
      readonly displayValue: string;
      readonly range: SourceRange;
    }
  | { readonly kind: "and"; readonly range: SourceRange }
  | { readonly kind: "or"; readonly range: SourceRange };

export type SearchTokenizeResult =
  | { readonly ok: true; readonly tokens: readonly SearchToken[] }
  | { readonly ok: false; readonly error: SearchParseError };

export class SearchQuerySyntaxError extends Error {
  readonly code: SearchParseErrorCode;
  readonly hint: string;
  readonly range: SourceRange;

  constructor(readonly detail: SearchParseError) {
    super(detail.message);
    this.name = "SearchQuerySyntaxError";
    this.code = detail.code;
    this.hint = detail.hint;
    this.range = detail.range;
  }
}
import { searchParseError, tokenizeSearchQuery } from "./tokenizer.js";
import {
  type AndSearchNode,
  type EmptySearchNode,
  type OrSearchNode,
  type SearchAst,
  type SearchExpression,
  type SearchParseError,
  type SearchParseResult,
  SearchQuerySyntaxError,
  type SearchToken,
  type SourceRange,
} from "./types.js";

const EMPTY: EmptySearchNode = Object.freeze({ kind: "Empty" });

function sourceRange(start: number, end: number): SourceRange {
  return Object.freeze({ start, end });
}

function expressionRange(expression: SearchExpression): SourceRange {
  return expression.range;
}

function atomFromToken(token: SearchToken): SearchExpression {
  switch (token.kind) {
    case "text":
      return Object.freeze({ kind: "Text", value: token.value, range: token.range });
    case "phrase":
      return Object.freeze({ kind: "Phrase", value: token.value, range: token.range });
    case "tag":
      return Object.freeze({
        kind: "Tag",
        displayValue: token.displayValue,
        normalizedValue: token.normalizedValue,
        range: token.range,
      });
    case "and":
    case "or":
      throw new Error("An operator cannot be converted to a search atom.");
  }
}

function andNode(left: SearchExpression, right: SearchExpression): AndSearchNode {
  return Object.freeze({
    kind: "And",
    left,
    right,
    range: sourceRange(expressionRange(left).start, expressionRange(right).end),
  });
}

function orNode(left: SearchExpression, right: SearchExpression): OrSearchNode {
  return Object.freeze({
    kind: "Or",
    left,
    right,
    range: sourceRange(expressionRange(left).start, expressionRange(right).end),
  });
}

function isOperator(
  token: SearchToken | undefined,
): token is Extract<SearchToken, { kind: "and" | "or" }> {
  return token?.kind === "and" || token?.kind === "or";
}

function isParseError(value: SearchExpression | SearchParseError): value is SearchParseError {
  return "code" in value;
}

class Parser {
  private cursor = 0;

  constructor(private readonly tokens: readonly SearchToken[]) {}

  parse(): SearchExpression | SearchParseError {
    const first = this.peek();
    if (first === undefined) throw new Error("Parser requires at least one token.");
    if (isOperator(first)) {
      return searchParseError("MISSING_LEFT_OPERAND", first.range.start, first.range.end);
    }

    let expression = this.parseAnd();
    if (isParseError(expression)) return expression;

    while (this.peek()?.kind === "or") {
      const operator = this.consume();
      const next = this.peek();
      if (next === undefined) {
        return searchParseError("MISSING_RIGHT_OPERAND", operator.range.start, operator.range.end);
      }
      if (isOperator(next)) {
        return searchParseError("DOUBLE_OPERATOR", next.range.start, next.range.end);
      }

      const right = this.parseAnd();
      if (isParseError(right)) return right;
      expression = orNode(expression, right);
    }

    return expression;
  }

  private parseAnd(): SearchExpression | SearchParseError {
    const first = this.consume();
    let expression = atomFromToken(first);

    while (true) {
      const token = this.peek();
      if (token === undefined || token.kind === "or") return expression;

      if (token.kind === "and") {
        const operator = this.consume();
        const next = this.peek();
        if (next === undefined) {
          return searchParseError(
            "MISSING_RIGHT_OPERAND",
            operator.range.start,
            operator.range.end,
          );
        }
        if (isOperator(next)) {
          return searchParseError("DOUBLE_OPERATOR", next.range.start, next.range.end);
        }
      }

      const rightToken = this.consume();
      if (isOperator(rightToken)) {
        return searchParseError("DOUBLE_OPERATOR", rightToken.range.start, rightToken.range.end);
      }
      expression = andNode(expression, atomFromToken(rightToken));
    }
  }

  private peek(): SearchToken | undefined {
    return this.tokens[this.cursor];
  }

  private consume(): SearchToken {
    const token = this.tokens[this.cursor];
    if (token === undefined) throw new Error("Unexpected end of token stream.");
    this.cursor += 1;
    return token;
  }
}

export function parseSearchQuery(source: string): SearchParseResult {
  const tokenized = tokenizeSearchQuery(source);
  if (!tokenized.ok) return tokenized;
  if (tokenized.tokens.length === 0) return Object.freeze({ ok: true, ast: EMPTY });

  const parsed = new Parser(tokenized.tokens).parse();
  if (isParseError(parsed)) {
    return Object.freeze({ ok: false, error: parsed });
  }
  return Object.freeze({ ok: true, ast: parsed });
}

export function parseSearchQueryOrThrow(source: string): SearchAst {
  const result = parseSearchQuery(source);
  if (!result.ok) throw new SearchQuerySyntaxError(result.error);
  return result.ast;
}
import { describe, expect, it } from "vitest";

import { parseSearchQuery, parseSearchQueryOrThrow } from "../../src/shared/search/parser.js";
import { tokenizeSearchQuery } from "../../src/shared/search/tokenizer.js";
import type {
  SearchAst,
  SearchParseError,
  SearchParseResult,
  SourceRange,
} from "../../src/shared/search/types.js";

function parse(source: string): SearchAst {
  return parseSearchQueryOrThrow(source);
}

function failure(source: string): SearchParseError {
  const result: SearchParseResult = parseSearchQuery(source);
  expect(result.ok).toBe(false);
  if (result.ok) throw new Error(`Expected ${JSON.stringify(source)} to be invalid`);
  return result.error;
}

function range(start: number, end: number): SourceRange {
  return { start, end };
}

describe("search grammar version 1 lexer", () => {
  it("emits atoms, case-insensitive operators, and stable end-exclusive source ranges", () => {
    expect(tokenizeSearchQuery('  Alpha aNd "two words" OR #news #"machine learning"  ')).toEqual({
      ok: true,
      tokens: [
        { kind: "text", value: "Alpha", range: range(2, 7) },
        { kind: "and", range: range(8, 11) },
        { kind: "phrase", value: "two words", range: range(12, 23) },
        { kind: "or", range: range(24, 26) },
        {
          kind: "tag",
          displayValue: "news",
          normalizedValue: "news",
          range: range(27, 32),
        },
        {
          kind: "tag",
          displayValue: "machine learning",
          normalizedValue: "machine learning",
          range: range(33, 52),
        },
      ],
    });
  });

  it("decodes only supported quote and backslash escapes", () => {
    expect(parse('"say \\"hello\\" \\\\ path"')).toMatchObject({
      kind: "Phrase",
      value: 'say "hello" \\ path',
      range: range(0, 23),
    });
  });

  it.each([
    ['"bad\\nvalue"', range(4, 6)],
    ['#"bad\\tvalue"', range(5, 7)],
    ['"trailing\\', range(9, 10)],
  ])("rejects an invalid quoted escape in %j", (source, expectedRange) => {
    expect(failure(source)).toEqual({
      code: "INVALID_ESCAPE",
      message: "Quoted text can escape only a quote or backslash.",
      hint: "Escape only a quote or backslash",
      range: expectedRange,
    });
  });
});

describe("search grammar version 1 parser", () => {
  it.each(["", " ", "\n\t "])("returns an immutable Empty AST for %j", (source) => {
    const ast = parse(source);
    expect(ast).toEqual({ kind: "Empty" });
    expect(Object.isFrozen(ast)).toBe(true);
  });

  it("parses each atom and preserves decoded display spelling", () => {
    expect(parse("Alpha")).toEqual({ kind: "Text", value: "Alpha", range: range(0, 5) });
    expect(parse('"Alpha beta"')).toEqual({
      kind: "Phrase",
      value: "Alpha beta",
      range: range(0, 12),
    });
    expect(parse("#NeWs")).toEqual({
      kind: "Tag",
      displayValue: "NeWs",
      normalizedValue: "news",
      range: range(0, 5),
    });
    expect(parse('#" Machine\tLearning "')).toEqual({
      kind: "Tag",
      displayValue: "Machine Learning",
      normalizedValue: "machine learning",
      range: range(0, 21),
    });
  });

  it("normalizes exact-tag keys with Unicode compatibility and locale-independent case", () => {
    expect(parse('#"  ＮＥＷＳ   Café  "')).toMatchObject({
      kind: "Tag",
      displayValue: "ＮＥＷＳ Café",
      normalizedValue: "news café",
    });
  });

  it("treats adjacent atoms as AND", () => {
    expect(parse("alpha beta")).toEqual({
      kind: "And",
      left: { kind: "Text", value: "alpha", range: range(0, 5) },
      right: { kind: "Text", value: "beta", range: range(6, 10) },
      range: range(0, 10),
    });
  });

  it("accepts explicit case-insensitive AND", () => {
    expect(parse("alpha aNd beta")).toMatchObject({
      kind: "And",
      left: { kind: "Text", value: "alpha" },
      right: { kind: "Text", value: "beta" },
      range: range(0, 14),
    });
  });

  it("binds explicit and implicit AND more tightly than OR", () => {
    expect(parse("alpha OR beta gamma")).toMatchObject({
      kind: "Or",
      left: { kind: "Text", value: "alpha" },
      right: {
        kind: "And",
        left: { kind: "Text", value: "beta" },
        right: { kind: "Text", value: "gamma" },
      },
      range: range(0, 19),
    });

    expect(parse("alpha AND beta OR gamma")).toMatchObject({
      kind: "Or",
      left: {
        kind: "And",
        left: { kind: "Text", value: "alpha" },
        right: { kind: "Text", value: "beta" },
      },
      right: { kind: "Text", value: "gamma" },
    });
  });

  it("parses the remaining contract precedence examples", () => {
    expect(parse('"alpha beta" #news')).toMatchObject({
      kind: "And",
      left: { kind: "Phrase", value: "alpha beta" },
      right: { kind: "Tag", normalizedValue: "news" },
    });
    expect(parse('#news OR #"machine learning"')).toMatchObject({
      kind: "Or",
      left: { kind: "Tag", normalizedValue: "news" },
      right: { kind: "Tag", normalizedValue: "machine learning" },
    });
    expect(parse('"AND" OR "OR"')).toMatchObject({
      kind: "Or",
      left: { kind: "Phrase", value: "AND" },
      right: { kind: "Phrase", value: "OR" },
    });
  });

  it("freezes every AST node and range", () => {
    const ast = parse("alpha beta OR #news");
    expect(Object.isFrozen(ast)).toBe(true);
    if (ast.kind !== "Or") throw new Error("Expected Or node");
    expect(Object.isFrozen(ast.range)).toBe(true);
    expect(Object.isFrozen(ast.left)).toBe(true);
    expect(Object.isFrozen(ast.right)).toBe(true);
    if (ast.left.kind !== "And") throw new Error("Expected And node");
    expect(Object.isFrozen(ast.left.left)).toBe(true);
    expect(Object.isFrozen(ast.left.right)).toBe(true);
  });
});

describe("search syntax guidance", () => {
  it.each([
    ['"alpha', "UNMATCHED_QUOTE", range(0, 6), "Close the quoted phrase"],
    ['#"alpha', "UNMATCHED_QUOTE", range(1, 7), "Close the quoted phrase"],
    ['""', "EMPTY_PHRASE", range(0, 2), "Add text inside the quotes"],
    ['"  \t"', "EMPTY_PHRASE", range(0, 5), "Add text inside the quotes"],
    ["#", "EMPTY_TAG", range(0, 1), "Add a tag name after `#`"],
    ['#""', "EMPTY_TAG", range(0, 3), "Add a tag name after `#`"],
    ['#" \t"', "EMPTY_TAG", range(0, 5), "Add a tag name after `#`"],
    ["OR alpha", "MISSING_LEFT_OPERAND", range(0, 2), "Add a search term before the operator"],
    ["and alpha", "MISSING_LEFT_OPERAND", range(0, 3), "Add a search term before the operator"],
    ["alpha AND", "MISSING_RIGHT_OPERAND", range(6, 9), "Add a search term after the operator"],
    ["alpha or  ", "MISSING_RIGHT_OPERAND", range(6, 8), "Add a search term after the operator"],
    [
      "alpha AND OR beta",
      "DOUBLE_OPERATOR",
      range(10, 12),
      "Remove one operator or add a term between them",
