const r = await tools.exec_command({"cmd":"node --import tsx --input-type=module -e '
import Database from "better-sqlite3";
import { TagRepository, normalizeTagName } from "./src/server/repositories/tag-repository.ts";
const db = new Database(":memory:");
db.exec(`CREATE TABLE bookmarks(id INTEGER PRIMARY KEY, archived_at TEXT); CREATE TABLE tags(id INTEGER PRIMARY KEY, display_name TEXT NOT NULL, name_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL); CREATE TABLE bookmark_tags(bookmark_id INTEGER NOT NULL, tag_id INTEGER NOT NULL, PRIMARY KEY(bookmark_id, tag_id));`);
db.prepare("INSERT INTO bookmarks VALUES (?, ?)").run(1, null);
db.prepare("INSERT INTO bookmarks VALUES (?, ?)").run(2, "archived");
for (const [id, name] of [[1, "News"], [2, "Machine Learning"]]) { const tag = normalizeTagName(name); db.prepare("INSERT INTO tags VALUES (?, ?, ?, ?)").run(id, tag.displayName, tag.nameKey, "now"); }
db.prepare("INSERT INTO bookmark_tags VALUES (?, ?)").run(1, 1); db.prepare("INSERT INTO bookmark_tags VALUES (?, ?)").run(2, 1);
const repository = new TagRepository(db);
console.log(JSON.stringify({ summaries: repository.listSummaries(), exact: repository.findExact(" ＮＥＷＳ "), partial: repository.findPartial("learn") }));
db.close();
