import { closeDatabase, openDatabase } from "../../src/server/db/database.js";
import { runMigrations } from "../../src/server/db/migrate.js";
import { MetadataCoordinator } from "../../src/server/services/metadata/metadata-coordinator.js";
import type { SafeFetchResult } from "../../src/server/services/metadata/safe-fetch.js";
import { createFastifyTestHarness } from "../helpers/fastify.js";

describe("durable bookmark capture", () => {
  const htmlResult = (html: string): SafeFetchResult => ({
    finalUrl: new URL("https://example.com/article"),
    statusCode: 200,
    headers: { "content-type": "text/html" },
    contentType: "text/html",
    body: Buffer.from(html),
  });

  it("saves a fallback immediately and survives a database reopen", async () => {
    const harness = await createFastifyTestHarness();
    const response = await harness.injectJson({
      method: "POST",
      url: "/api/bookmarks",
      payload: { address: "https://example.com/long-story", unread: true },
    });
    expect(response.statusCode).toBe(201);
    expect(response.json()).toMatchObject({
      address: "https://example.com/long-story",
      title: "Long story — example.com",
      titleProvenance: "fallback",
      metadataStatus: "pending",
      unread: true,
    });

    const id = response.json().id as number;
    const databasePath = harness.testDatabase.databasePath;
    await harness.app.close();
    closeDatabase(harness.testDatabase.database);

    const reopened = openDatabase(databasePath);
    runMigrations(reopened);
    expect(reopened.prepare("SELECT id, is_unread FROM bookmarks WHERE id = ?").get(id)).toEqual({
      id,
      is_unread: 1,
    });
    closeDatabase(reopened);
    harness.testDatabase.cleanup();
  });

  it("keeps one row under normalized duplicate attempts, including archived rows", async () => {
    const harness = await createFastifyTestHarness();
    try {
      const first = await harness.injectJson({
        method: "POST",
        url: "/api/bookmarks",
        payload: { address: "https://example.com/item" },
      });
      const id = first.json().id as number;
      harness.testDatabase.database
        .prepare("UPDATE bookmarks SET archived_at = ? WHERE id = ?")
        .run("2026-09-17T00:00:00.000Z", id);

      const second = await harness.injectJson({
        method: "POST",
        url: "/api/bookmarks",
        payload: { address: "https://EXAMPLE.com:443/item" },
      });
      expect(second.statusCode).toBe(409);
      expect(second.json()).toMatchObject({ existingBookmarkId: id, existingScope: "archived" });
      expect(
        harness.testDatabase.database.prepare("SELECT count(*) AS count FROM bookmarks").get(),
      ).toEqual({ count: 1 });
    } finally {
      await harness.close();
    }
  });

  it("marks supplied text as user-authored so enrichment cannot clobber it", async () => {
    const harness = await createFastifyTestHarness();
    try {
      const response = await harness.injectJson({
        method: "POST",
        url: "/api/bookmarks",
        payload: {
          address: "https://example.com/custom",
          title: "My title",
          description: "My description",
        },
      });
      expect(response.statusCode).toBe(201);
      expect(response.json()).toMatchObject({
        title: "My title",
        titleProvenance: "user",
        description: "My description",
        descriptionProvenance: "user",
      });

      const row = harness.testDatabase.database
        .prepare(
          "SELECT title_provenance, description_provenance, address_revision FROM bookmarks WHERE id = ?",
        )
        .get(response.json().id);
      expect(row).toEqual({
        title_provenance: "user",
        description_provenance: "user",
        address_revision: 1,
      });
    } finally {
      await harness.close();
    }
  });

  it("restarts pending jobs and preserves user fields as retrieved candidates", async () => {
    const harness = await createFastifyTestHarness();
    try {
      const created = await harness.injectJson({
        method: "POST",
        url: "/api/bookmarks",
        payload: { address: "https://example.com/article", title: "Kept title" },
      });
      const coordinator = new MetadataCoordinator({
        database: harness.testDatabase.database,
        config: harness.config.metadata,
        now: harness.clock.now,
        fetch: {
          html: async () =>
            htmlResult(
              '<title>Retrieved title</title><meta name="description" content="Retrieved description">',
            ),
          icon: async () => {
            throw new Error("no icon");
          },
        },
      });
      coordinator.start();
      await coordinator.drain();

      expect(
        await harness
          .injectJson({ method: "GET", url: `/api/bookmarks/${created.json().id}` })
          .then((response) => response.json()),
      ).toMatchObject({
        title: "Kept title",
        titleProvenance: "user",
        retrievedTitleCandidate: "Retrieved title",
        description: "Retrieved description",
        descriptionProvenance: "retrieved",
        metadataStatus: "complete",
      });
    } finally {
      await harness.close();
    }
  });

  it("ignores an enrichment result after the address revision changes", async () => {
    const harness = await createFastifyTestHarness();
    let release: (() => void) | undefined;
    const blocked = new Promise<void>((resolve) => {
      release = resolve;
    });
    try {
      const created = await harness.injectJson({
        method: "POST",
        url: "/api/bookmarks",
        payload: { address: "https://example.com/article" },
      });
      const coordinator = new MetadataCoordinator({
        database: harness.testDatabase.database,
        config: harness.config.metadata,
        fetch: {
          html: async () => {
            await blocked;
            return htmlResult("<title>Stale title</title>");
          },
          icon: async () => {
            throw new Error("no icon");
          },
        },
      });
      coordinator.enqueue(created.json().id, created.json().address, 1);
      harness.testDatabase.database
        .prepare("UPDATE bookmarks SET address_revision = 2 WHERE id = ?")
        .run(created.json().id);
      release?.();
      await coordinator.drain();
      const row = harness.testDatabase.database
        .prepare("SELECT title, metadata_status FROM bookmarks WHERE id = ?")
        .get(created.json().id);
      expect(row).toEqual({ title: "Article — example.com", metadata_status: "pending" });
    } finally {
      await harness.close();
    }
  });
});
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { type AppDatabase, closeDatabase, openDatabase } from "../../src/server/db/database.js";
import { runMigrations } from "../../src/server/db/migrate.js";

const DEFAULT_MIGRATIONS_DIRECTORY = fileURLToPath(new URL("../../migrations/", import.meta.url));

export interface TestDatabaseOptions {
  migrate?: boolean;
  migrationsDirectory?: string;
  prefix?: string;
}

export interface TestDatabase {
  database: AppDatabase;
  databasePath: string;
  directory: string;
  appliedMigrations: readonly number[];
  cleanup: () => void;
}

/**
 * Creates a real, file-backed database so WAL, locking, and uniqueness behavior
 * match production. Every call owns a separate mkdtemp directory.
 */
export function createTestDatabase(options: TestDatabaseOptions = {}): TestDatabase {
  const directory = mkdtempSync(path.join(tmpdir(), options.prefix ?? "bookmark-garden-test-"));
  const databasePath = path.join(directory, "bookmarks.sqlite");
  const database = openDatabase(databasePath);
  let cleaned = false;

  try {
    const appliedMigrations =
      options.migrate === false
        ? []
        : runMigrations(database, options.migrationsDirectory ?? DEFAULT_MIGRATIONS_DIRECTORY);

    return {
      database,
      databasePath,
      directory,
      appliedMigrations,
      cleanup: () => {
        if (cleaned) return;
        cleaned = true;
        closeDatabase(database);
        rmSync(directory, { recursive: true, force: true });
      },
    };
  } catch (error) {
    closeDatabase(database);
    rmSync(directory, { recursive: true, force: true });
    throw error;
  }
}

export async function withTestDatabase<T>(
  run: (fixture: TestDatabase) => T | Promise<T>,
  options: TestDatabaseOptions = {},
): Promise<T> {
  const fixture = createTestDatabase(options);
  try {
    return await run(fixture);
  } finally {
    fixture.cleanup();
  }
}
import { DEFAULT_TEST_TIME } from "./clock.js";

export type MetadataStatus = "pending" | "complete" | "partial" | "failed" | "skipped_unsafe";
export type Provenance = "fallback" | "retrieved" | "user";
export type Scope = "active" | "read_later" | "archived";
export type SortOrder = "created_desc" | "created_asc" | "updated_desc" | "title_asc";

export interface TagFixture {
  id: number;
  name: string;
}

export interface BookmarkFixture {
  id: number;
  address: string;
  title: string;
  titleProvenance: Provenance;
  retrievedTitleCandidate: string | null;
  description: string;
  descriptionProvenance: Provenance;
  retrievedDescriptionCandidate: string | null;
  iconUrl: string | null;
  metadataStatus: MetadataStatus;
  metadataErrorCode: string | null;
  noteMarkdown: string;
  tags: TagFixture[];
  favorite: boolean;
  unread: boolean;
  archived: boolean;
  createdAt: string;
  updatedAt: string;
}

export interface BookmarkRowFixture {
  id: number;
  address: string;
  normalized_address: string;
  address_revision: number;
  title: string;
  title_sort_key: string;
  title_provenance: Provenance;
  retrieved_title_candidate: string | null;
  description: string;
  description_provenance: Provenance;
  retrieved_description_candidate: string | null;
  icon_hash: string | null;
  metadata_status: MetadataStatus;
  metadata_error_code: string | null;
  metadata_fetched_at: string | null;
  note_markdown: string;
  note_plain: string;
  is_favorite: 0 | 1;
  is_unread: 0 | 1;
  archived_at: string | null;
  created_at: string;
  updated_at: string;
}

export interface SearchCriteriaFixture {
  scope: Scope;
  query: string;
  tags: string[];
  favorite: boolean | null;
  unread: boolean | null;
  sort: SortOrder;
}

export interface SavedViewFixture extends SearchCriteriaFixture {
  id: number;
  name: string;
  grammarVersion: 1;
  createdAt: string;
  updatedAt: string;
}

export interface SelectionFixture {
  id: string;
  selectedCount: number;
  criteriaHash: string;
  expiresAt: string;
}

function fixtureAddress(id: number): string {
  return `https://example.test/articles/${id}`;
}

export function makeTag(overrides: Partial<TagFixture> = {}): TagFixture {
  const id = overrides.id ?? 1;
  return { id, name: overrides.name ?? `Tag ${id}` };
}

export function makeBookmark(overrides: Partial<BookmarkFixture> = {}): BookmarkFixture {
  const id = overrides.id ?? 1;
  return {
    id,
    address: fixtureAddress(id),
    title: `Example bookmark ${id}`,
    titleProvenance: "retrieved",
    retrievedTitleCandidate: null,
    description: `A deterministic description for bookmark ${id}.`,
    descriptionProvenance: "retrieved",
    retrievedDescriptionCandidate: null,
    iconUrl: `/api/bookmarks/${id}/icon`,
    metadataStatus: "complete",
    metadataErrorCode: null,
    noteMarkdown: "",
    favorite: false,
    unread: false,
    archived: false,
    createdAt: DEFAULT_TEST_TIME,
    updatedAt: DEFAULT_TEST_TIME,
    ...overrides,
    tags: overrides.tags ? [...overrides.tags] : [],
  };
}

export function makeBookmarkRow(overrides: Partial<BookmarkRowFixture> = {}): BookmarkRowFixture {
  const id = overrides.id ?? 1;
  const address = overrides.address ?? fixtureAddress(id);
  const title = overrides.title ?? `Example bookmark ${id}`;
  return {
    id,
    address,
    normalized_address: overrides.normalized_address ?? address,
    address_revision: 1,
    title,
    title_sort_key: overrides.title_sort_key ?? title.normalize("NFKC").toLowerCase(),
    title_provenance: "retrieved",
    retrieved_title_candidate: null,
    description: `A deterministic description for bookmark ${id}.`,
    description_provenance: "retrieved",
    retrieved_description_candidate: null,
    icon_hash: null,
    metadata_status: "complete",
    metadata_error_code: null,
    metadata_fetched_at: DEFAULT_TEST_TIME,
    note_markdown: "",
    note_plain: "",
    is_favorite: 0,
    is_unread: 0,
    archived_at: null,
    created_at: DEFAULT_TEST_TIME,
    updated_at: DEFAULT_TEST_TIME,
    ...overrides,
  };
}

export function makeSearchCriteria(
  overrides: Partial<SearchCriteriaFixture> = {},
): SearchCriteriaFixture {
  return {
    scope: "active",
    query: "",
    favorite: null,
    unread: null,
    sort: "created_desc",
    ...overrides,
    tags: overrides.tags ? [...overrides.tags] : [],
  };
}

export function makeSavedView(overrides: Partial<SavedViewFixture> = {}): SavedViewFixture {
  const id = overrides.id ?? 1;
  return {
    ...makeSearchCriteria(overrides),
    id,
    name: overrides.name ?? `Saved view ${id}`,
    grammarVersion: 1,
    createdAt: DEFAULT_TEST_TIME,
    updatedAt: DEFAULT_TEST_TIME,
    ...overrides,
    tags: overrides.tags ? [...overrides.tags] : [],
  };
}

export function makeSelection(overrides: Partial<SelectionFixture> = {}): SelectionFixture {
  return {
    id: "selection-00000001",
    selectedCount: 1,
    criteriaHash: "sha256:deterministic-criteria-hash",
    expiresAt: "2026-01-02T03:19:05.000Z",
    ...overrides,
  };
}

export interface EntityFactories {
  bookmark: (overrides?: Partial<BookmarkFixture>) => BookmarkFixture;
  bookmarkRow: (overrides?: Partial<BookmarkRowFixture>) => BookmarkRowFixture;
  tag: (overrides?: Partial<TagFixture>) => TagFixture;
  savedView: (overrides?: Partial<SavedViewFixture>) => SavedViewFixture;
  selection: (overrides?: Partial<SelectionFixture>) => SelectionFixture;
  reset: () => void;
}

/** Returns sequence-backed factories for tests that need many distinct entities. */
export function createEntityFactories(): EntityFactories {
  let bookmarkId = 0;
  let tagId = 0;
  let savedViewId = 0;
  let selectionId = 0;

  return {
    bookmark: (overrides = {}) => makeBookmark({ id: ++bookmarkId, ...overrides }),
    bookmarkRow: (overrides = {}) => makeBookmarkRow({ id: ++bookmarkId, ...overrides }),
    tag: (overrides = {}) => makeTag({ id: ++tagId, ...overrides }),
    savedView: (overrides = {}) => makeSavedView({ id: ++savedViewId, ...overrides }),
    selection: (overrides = {}) =>
      makeSelection({ id: `selection-${String(++selectionId).padStart(8, "0")}`, ...overrides }),
    reset: () => {
      bookmarkId = 0;
      tagId = 0;
      savedViewId = 0;
      selectionId = 0;
    },
  };
}

