  it("returns position-aware syntax guidance and does not persist an invalid view", async () => {
    await withFastifyTestHarness(async ({ injectJson }) => {
      const response = await injectJson({
        method: "POST",
        url: "/api/saved-views",
        payload: payload({ query: "alpha AND OR beta" }),
