    </Dialog>
  );
}
import { type FormEvent, useState } from "react";
import { Button, Status, TextAreaField, TextField } from "../../components";
import { ApiError, api, type Bookmark, type BookmarkApiClient, type Scope } from "../../lib/api";
import { NoteEditor } from "./NoteEditor";

export interface BookmarkEditorProps {
  bookmark: Bookmark;
  client?: BookmarkApiClient | undefined;
  onSaved: (bookmark: Bookmark) => void;
  onCancel: () => void;
  onDuplicate: (bookmarkId: number, scope?: Scope) => void;
}

function normalizeTags(value: string): string[] {
  const result: string[] = [];
  const seen = new Set<string>();
  for (const raw of value.split(",")) {
    const tag = raw.trim();
    const key = tag.toLocaleLowerCase();
    if (!tag || seen.has(key)) continue;
    seen.add(key);
    result.push(tag);
  }
  return result;
}

export function BookmarkEditor({
  bookmark,
  client = api,
  onSaved,
  onCancel,
  onDuplicate,
}: BookmarkEditorProps) {
  const [address, setAddress] = useState(bookmark.address);
  const [title, setTitle] = useState(bookmark.title);
  const [description, setDescription] = useState(bookmark.description);
  const [tags, setTags] = useState(bookmark.tags.map((tag) => tag.name).join(", "));
  const [noteMarkdown, setNoteMarkdown] = useState(bookmark.noteMarkdown);
  const [acceptTitle, setAcceptTitle] = useState(false);
  const [acceptDescription, setAcceptDescription] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSaving(true);
    setError(null);
    const controller = new AbortController();
    try {
      const updated = await client.updateBookmark(
        bookmark.id,
        {
          ...(address.trim() !== bookmark.address ? { address: address.trim() } : {}),
          ...(!acceptTitle && title.trim() !== bookmark.title ? { title: title.trim() } : {}),
          ...(!acceptDescription && description.trim() !== bookmark.description
            ? { description: description.trim() }
            : {}),
          ...(noteMarkdown !== bookmark.noteMarkdown ? { noteMarkdown } : {}),
          ...(tags !== bookmark.tags.map((tag) => tag.name).join(", ")
            ? { tags: normalizeTags(tags) }
            : {}),
          ...(acceptTitle ? { acceptRetrievedTitle: true } : {}),
          ...(acceptDescription ? { acceptRetrievedDescription: true } : {}),
        },
        { signal: controller.signal },
      );
      onSaved(updated);
    } catch (cause) {
      if (
        cause instanceof ApiError &&
        cause.problem.code === "DUPLICATE_BOOKMARK" &&
        "existingBookmarkId" in cause.problem
      ) {
        onDuplicate(cause.problem.existingBookmarkId, cause.problem.existingScope);
      } else {
        setError(
          cause instanceof ApiError
            ? cause.problem.message
            : "The bookmark could not be updated. Please try again.",
        );
      }
    } finally {
      setSaving(false);
    }
  }

  return (
    <form className="bookmark-editor" onSubmit={submit}>
      <TextField
        id="bookmark-edit-address"
        label="Web address"
        type="url"
        required
        value={address}
        onChange={(event) => setAddress(event.currentTarget.value)}
      />
      <div className="bookmark-editor__candidate-field">
        <TextField
          id="bookmark-edit-title"
          label="Title"
          required
          value={title}
          onChange={(event) => {
            setAcceptTitle(false);
            setTitle(event.currentTarget.value);
          }}
        />
        {bookmark.retrievedTitleCandidate && bookmark.retrievedTitleCandidate !== bookmark.title ? (
          <div className="metadata-candidate">
            <span>Retrieved suggestion: {bookmark.retrievedTitleCandidate}</span>
            <Button
              size="small"
              variant="quiet"
              onClick={() => {
                setTitle(bookmark.retrievedTitleCandidate ?? title);
                setAcceptTitle(true);
              }}
            >
              Use retrieved title
            </Button>
          </div>
        ) : null}
      </div>
      <div className="bookmark-editor__candidate-field">
        <TextAreaField
          id="bookmark-edit-description"
          label="Description"
          rows={3}
          value={description}
          onChange={(event) => {
            setAcceptDescription(false);
            setDescription(event.currentTarget.value);
          }}
        />
        {bookmark.retrievedDescriptionCandidate &&
        bookmark.retrievedDescriptionCandidate !== bookmark.description ? (
          <div className="metadata-candidate">
            <span>Retrieved suggestion: {bookmark.retrievedDescriptionCandidate}</span>
            <Button
              size="small"
              variant="quiet"
              onClick={() => {
                setDescription(bookmark.retrievedDescriptionCandidate ?? description);
                setAcceptDescription(true);
              }}
            >
              Use retrieved description
            </Button>
          </div>
        ) : null}
      </div>
      <TextField
        id="bookmark-edit-tags"
        label="Tags"
        value={tags}
        hint="Separate tags with commas. Capitalization-only duplicates are combined."
        onChange={(event) => setTags(event.currentTarget.value)}
      />
      <NoteEditor value={noteMarkdown} onChange={setNoteMarkdown} />
      {error ? <Status tone="error">{error}</Status> : null}
      <div className="bookmark-editor__actions">
        <Button variant="quiet" onClick={onCancel}>
          Cancel
        </Button>
        <Button type="submit" variant="primary" busy={saving} busyLabel="Saving changes…">
          Save changes
        </Button>
      </div>
    </form>
  );
}
import { useState } from "react";
import { Button, Status } from "../../components";
import { api, type Bookmark, type BookmarkApiClient } from "../../lib/api";

export interface BookmarkActionsProps {
  bookmark: Bookmark;
  client?: BookmarkApiClient | undefined;
  onUpdated: (bookmark: Bookmark, outcome?: string) => void;
}

type PendingAction = "favorite" | "archive" | "refresh" | null;

export function BookmarkActions({ bookmark, client = api, onUpdated }: BookmarkActionsProps) {
  const [pending, setPending] = useState<PendingAction>(null);
  const [outcome, setOutcome] = useState("");
  const [failed, setFailed] = useState(false);

  async function patch(
    action: Exclude<PendingAction, "refresh" | null>,
    change: { favorite: boolean } | { archived: boolean },
    message: string,
  ) {
    setPending(action);
    setFailed(false);
    try {
      const updated = await client.updateBookmark(bookmark.id, change);
      const retention = "archived" in change && bookmark.unread ? " Read Later retained." : "";
      const result = `${message}${retention}`;
      setOutcome(result);
      onUpdated(updated, result);
    } catch {
      setFailed(true);
      setOutcome("The bookmark could not be changed. Please try again.");
    } finally {
      setPending(null);
    }
  }

  async function refresh() {
    setPending("refresh");
    setFailed(false);
    try {
      await client.refreshBookmarkMetadata(bookmark.id);
      setOutcome("Page detail refresh started. Your custom text will be kept.");
    } catch {
      setFailed(true);
      setOutcome("Page details could not be refreshed. Please try again.");
    } finally {
      setPending(null);
    }
  }

  return (
    <section className="bookmark-actions" aria-label="Bookmark actions">
      <div className="bookmark-actions__buttons">
        <Button
          busy={pending === "favorite"}
          busyLabel="Updating…"
          onClick={() =>
            patch(
              "favorite",
              { favorite: !bookmark.favorite },
              bookmark.favorite ? "Removed from favorites." : "Added to favorites.",
            )
          }
        >
          {bookmark.favorite ? "Remove from favorites" : "Add to favorites"}
        </Button>
        <Button
          busy={pending === "archive"}
          busyLabel="Updating…"
          onClick={() =>
            patch(
              "archive",
              { archived: !bookmark.archived },
              bookmark.archived ? "Bookmark restored." : "Bookmark archived.",
            )
          }
        >
          {bookmark.archived ? "Restore bookmark" : "Archive bookmark"}
        </Button>
        <Button
          variant="quiet"
          busy={pending === "refresh"}
          busyLabel="Starting refresh…"
          onClick={refresh}
        >
          Refresh page details
        </Button>
      </div>
      <Status tone={failed ? "error" : outcome ? "success" : "neutral"}>
        {outcome || "Bookmark actions ready."}
      </Status>
    </section>
  );
}
