        .prepare(
          "SELECT display_name FROM saved_view_tags WHERE saved_view_id = ? ORDER BY tag_key",
        )
        .all(id) as Array<{ display_name: string }>
    ).map(({ display_name }) => display_name);
  }

  private toSavedView(row: SavedViewRow): SavedView {
    return {
      id: row.id,
      name: row.display_name,
      query: row.query_text,
      tags: this.tagsFor(row.id),
      scope: row.scope,
      favorite: nullableBoolean(row.favorite_filter),
      unread: nullableBoolean(row.unread_filter),
      sort: row.sort_order,
      grammarVersion: row.grammar_version,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }
}
import type { SavedView, SavedViewWrite, SearchCriteria } from "../../../shared/contracts/api.js";
import { parseSearchQueryOrThrow } from "../../../shared/search/parser.js";
import { normalizeExactTag } from "../../../shared/search/tokenizer.js";
import { SEARCH_GRAMMAR_VERSION } from "../../../shared/search/types.js";
import {
  normalizeSavedViewName,
  type SavedViewMutation,
  type SavedViewRepository,
} from "../../repositories/saved-view-repository.js";

function normalizedTags(tags: readonly string[]): SavedViewMutation["tags"] {
  const byKey = new Map<string, { displayName: string; tagKey: string }>();
  for (const value of tags) {
    const displayName = value.replace(/\s+/gu, " ").trim();
    const tagKey = normalizeExactTag(displayName);
    if (tagKey !== "" && !byKey.has(tagKey)) byKey.set(tagKey, { displayName, tagKey });
  }
  return [...byKey.values()].sort((left, right) =>
    left.tagKey < right.tagKey ? -1 : left.tagKey > right.tagKey ? 1 : 0,
  );
}

export function toSearchCriteria(view: SavedView): SearchCriteria {
  if (view.grammarVersion !== SEARCH_GRAMMAR_VERSION) {
    throw new Error(`Unsupported saved-view grammar version: ${view.grammarVersion}`);
  }
  parseSearchQueryOrThrow(view.query);
  return {
    scope: view.scope,
    query: view.query,
    tags: [...view.tags],
    favorite: view.favorite ?? null,
    unread: view.unread ?? null,
    sort: view.sort,
  };
}

export class SavedViewService {
  constructor(
    private readonly savedViews: SavedViewRepository,
    private readonly now: () => Date = () => new Date(),
  ) {}

  list(): SavedView[] {
    return this.savedViews.list();
  }

  get(id: number): SavedView {
    return this.savedViews.get(id);
  }

  create(input: SavedViewWrite): SavedView {
    return this.savedViews.create(this.values(input));
  }

  update(id: number, input: SavedViewWrite): SavedView {
    return this.savedViews.update(id, this.values(input));
  }

  delete(id: number): void {
    this.savedViews.delete(id);
  }

  criteriaFor(id: number): SearchCriteria {
    return toSearchCriteria(this.get(id));
  }

  private values(input: SavedViewWrite): SavedViewMutation {
    parseSearchQueryOrThrow(input.query);
    return {
      name: normalizeSavedViewName(input.name),
      query: input.query,
      tags: normalizedTags(input.tags),
      scope: input.scope,
      favorite: input.favorite ?? null,
      unread: input.unread ?? null,
      sort: input.sort,
      now: this.now().toISOString(),
    };
  }
}
import type { FastifyInstance, FastifyReply } from "fastify";

import {
  type SavedViewIdParams,
  SavedViewIdParamsSchema,
  SavedViewListSchema,
  SavedViewSchema,
  type SavedViewWrite,
  SavedViewWriteSchema,
} from "../../shared/contracts/api.js";
import { SearchQuerySyntaxError } from "../../shared/search/types.js";
import {
  DuplicateSavedViewNameError,
  InvalidSavedViewNameError,
  SavedViewNotFoundError,
  SavedViewRepository,
} from "../repositories/saved-view-repository.js";
import { SavedViewService } from "../services/search/saved-view-service.js";

function sendSavedViewError(reply: FastifyReply, error: unknown) {
  if (error instanceof DuplicateSavedViewNameError) {
    return reply.code(409).send({
      code: "DUPLICATE_SAVED_VIEW_NAME",
      message: error.message,
      field: "name",
    });
  }
  if (error instanceof SavedViewNotFoundError) {
    return reply.code(404).send({ code: "SAVED_VIEW_NOT_FOUND", message: error.message });
  }
  if (error instanceof SearchQuerySyntaxError) {
    return reply.code(422).send({
      code: error.code,
      message: error.message,
      field: "query",
      start: error.range.start,
      end: error.range.end,
      hint: error.hint,
    });
  }
  if (error instanceof InvalidSavedViewNameError) {
    return reply.code(422).send({
      code: error.code,
      message: error.message,
      field: error.field,
      start: 0,
      end: error.sourceLength,
      hint: error.hint,
    });
  }
  throw error;
}

export async function registerSavedViewRoutes(app: FastifyInstance): Promise<void> {
  const service = new SavedViewService(new SavedViewRepository(app.database), app.now);

  app.get("/api/saved-views", { schema: { response: { 200: SavedViewListSchema } } }, async () =>
    service.list(),
  );

  app.post<{ Body: SavedViewWrite }>(
    "/api/saved-views",
    { schema: { body: SavedViewWriteSchema, response: { 201: SavedViewSchema } } },
    async (request, reply) => {
      try {
        return reply.code(201).send(service.create(request.body));
      } catch (error) {
        return sendSavedViewError(reply, error);
      }
    },
  );

  app.patch<{ Params: SavedViewIdParams; Body: SavedViewWrite }>(
    "/api/saved-views/:savedViewId",
    {
      schema: {
        params: SavedViewIdParamsSchema,
        body: SavedViewWriteSchema,
        response: { 200: SavedViewSchema },
      },
    },
    async (request, reply) => {
      try {
        return service.update(request.params.savedViewId, request.body);
      } catch (error) {
        return sendSavedViewError(reply, error);
      }
    },
  );

  app.delete<{ Params: SavedViewIdParams }>(
    "/api/saved-views/:savedViewId",
    { schema: { params: SavedViewIdParamsSchema } },
    async (request, reply) => {
      try {
        service.delete(request.params.savedViewId);
        return reply.code(204).send();
      } catch (error) {
        return sendSavedViewError(reply, error);
      }
    },
  );
}

