      status: 200,
      contentType: "application/json",
      body: JSON.stringify({
        address: enrichedAddress,
        status: "complete",
        fallbackTitle: "Enriched article — bookmark-fixture.invalid",
        title: retrievedTitle,
        description: retrievedDescription,
        iconAvailable: false,
        errorCode: null,
      }),
    });
  });
}

