    await expect.poll(() => new URL(page.url()).searchParams.get("q")).toBeNull();
    await expect.poll(() => new URL(page.url()).searchParams.get("favorite")).toBeNull();
    await expect.poll(() => new URL(page.url()).searchParams.get("unread")).toBeNull();
  });
});
