  type ViewState,
  viewStateHref,
  withScope,
  writeViewState,
} from "../lib/view-state";

type StartupState = "loading" | "ready" | "error";

const scopeCopy = {
  active: {
    label: "Bookmarks",
    eyebrow: "Your collection",
    title: "A calmer place for the links worth keeping.",
