.app-layout {
  display: grid;
  grid-template-columns: minmax(12.5rem, 15rem) minmax(0, 1fr);
  width: min(100%, 96rem);
  min-height: calc(100vh - 8.5rem);
  margin: 0 auto;
}

.sidebar {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-width: 0;
  gap: 2rem;
  padding: 2rem 1.25rem 2rem clamp(1rem, 3vw, 2rem);
  border-right: 1px solid var(--line);
}

.nav-label,
.eyebrow {
  margin: 0 0 0.6rem;
  color: var(--leaf-700);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.nav-list {
  display: grid;
  gap: 0.35rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.nav-link {
  display: flex;
  min-height: 2.75rem;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
  border-radius: var(--radius-small);
  padding: 0.55rem 0.75rem;
  color: var(--ink-600);
  font-weight: 650;
  text-decoration: none;
}

.nav-count {
  display: inline-grid;
  min-width: 1.65rem;
  min-height: 1.65rem;
  place-items: center;
  border-radius: 999px;
  padding-inline: 0.35rem;
  background: var(--surface-raised);
  color: var(--leaf-700);
  font-size: 0.74rem;
  font-weight: 800;
}

.nav-link:hover {
  background: rgba(225, 237, 223, 0.6);
  color: var(--leaf-700);
}

.nav-link--active {
  background: var(--leaf-100);
  color: var(--leaf-700);
  box-shadow: inset 3px 0 var(--leaf-600);
}

.sidebar-note {
  padding: 1rem;
  border: 1px solid #ead5a9;
  border-radius: var(--radius-medium);
  background: var(--sun-100);
  color: #6b5125;
  font-size: 0.82rem;
}

.sidebar-note span {
  color: #ad781b;
}

.sidebar-note p {
  margin: 0.4rem 0 0;
}

.saved-views-nav {
  min-width: 0;
  margin-top: auto;
  padding-top: 1.25rem;
}

.saved-views-nav__heading,
.saved-view-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.35rem;
}

.saved-views-nav__heading .nav-label {
  margin: 0;
}

.saved-view-list {
  display: grid;
  min-width: 0;
  gap: 0.2rem;
  margin: 0.5rem 0 0;
  padding: 0;
  list-style: none;
}

.saved-view-list li {
  min-width: 0;
  border-radius: var(--radius-small);
}

.saved-view-list li > .button:first-child {
  overflow: hidden;
  min-width: 0;
  justify-content: start;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.saved-view-list li > div {
  display: flex;
  flex: 0 0 auto;
}

.saved-view--active {
  background: var(--leaf-100);
}

