        }
        throw error;
      }
    },
  );

  app.patch<{ Params: BookmarkIdParams; Body: BookmarkPatch }>(
    "/api/bookmarks/:bookmarkId",
    { schema: { params: BookmarkIdParamsSchema, body: BookmarkPatchSchema } },
